/// Return the pinned Unicode Word_Break property without consulting host data.
pub fn property(cp: u21) Property {
    var lo: usize = 0;
    var hi: usize = ranges.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const range = ranges[mid];
        if (cp < range.first) {
            hi = mid;
        } else if (cp > range.last) {
            lo = mid + 1;
        } else {
            return range.property;
        }
    }
    return .other;
}
